import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        amount = float(data.split()[0])
    except ValueError:
        return

    if amount >= 1000:
        discount = amount * 0.20
    elif amount >= 500:
        discount = amount * 0.10
    else:
        discount = 0.0

    final_price = amount - discount
    print(f"Discount: {discount:.2f}, Final Price: {final_price:.2f}")

if __name__ == "__main__":
    main()
